Here's a C++ program that uses a recursive function to generate the Fibonacci sequence, starting with two given integers as the first two sequence elements:

```cpp
#include <iostream>
#include <string>
#include <vector>

using namespace std;

// Function to generate the Fibonacci sequence
vector<int> fibonacci(int n, int a, int b) {
    if (n == 0) {
        return vector<int>();
    }

    vector<int> sequence = fibonacci(n - 1, b, a + b);
    sequence.push_back(a);

    return sequence;
}

int main() {
    string input;
    int num1, num2, numElements;

    cout << "Enter the first two integers: ";
    cin >> num1 >> num2;

    if (cin.fail()) {
        cout << "Invalid input. Please enter numeric values." << endl;
        return 1;
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> numElements;

    if (numElements <= 0) {
        cout << "Invalid input. Please enter a positive integer value." << endl;
        return 1;
    }

    vector<int> sequence = fibonacci(numElements, num1, num2);

    cout << "Fibonacci sequence: ";
    for (int i = 0; i < sequence.size(); i++) {
        cout << sequence[i] << ", ";
    }
    cout << endl;

    return 0;
}
```

