  'banana',
  'grapes',
  'dragon fruit',
  'green apple',
  'jack fruit',
  'lemon'
]
```

As you can see, the items with `randomize` set to `false` have been placed at their respective positions in the output array, while the items with `randomize` set to `true` have been randomly inserted into the array.

To retrieve the username from the JWT token in ASP.NET C# WebAPI, you can follow these steps:

1. Install the `Microsoft.IdentityModel.Tokens` package if you haven't already. You can install it using NuGet Package Manager or by running the following command in the terminal:
```
dotnet add package Microsoft.IdentityModel.Tokens
```
2. In your WebAPI project, create a new class that will handle the JWT token validation and retrieval. For example:
```csharp
using System;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using Microsoft.IdentityModel.Tokens;

public class JwtService
{
    private readonly TokenValidationParameters _validationParameters;

    public JwtService(string key)
    {
        _validationParameters = new TokenValidationParameters
        {
            IssuerSigningKey = key,
            ValidateIssuer = false,
            ValidateAudience = false,
            ValidateLifetime = true,
            ClockSkew = TimeSpan.Zero
        };
    }

    public string GetUsernameFromToken(string token)
    {
        var tokenHandler = new JwtSecurityTokenHandler();
        var securityToken = tokenHandler.ReadJwtToken(token);
        var claims = securityToken.Claims;

        foreach (var claim in claims)
        {
            if (claim.Type == "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/name" && claim.Value != null)
            {
                return claim.Value;
            }
        }

        return null;
    }
}
```
3. In your WebAPI controller, inject the `JwtService` class and use it to retrieve the username from the JWT token. For example:
```csharp
