```python
import argparse
import boto3

def get_failed_workflows(step_function_client):
    response = step_function_client.list_workflows()
    failed_workflows = []
    for workflow in response['workflows']:
        if workflow['status'] == 'FAILED':
            failed_workflows.append(workflow)
    return failed_workflows

def retrieve_inputs_and_names(failed_workflows):
    inputs_and_names = {}
    for workflow in failed_workflows:
        response = step_function_client.get_workflow_definition(workflow['id'])
        inputs_and_names[workflow['name']] = response['input']
    return inputs_and_names

def re_execute_workflows(step_function_client, inputs_and_names):
    for name, input in inputs_and_names.items():
        retry_name = f"{name} retry"
        response = step_function_client.start_workflow(
            name=retry_name,
            input=input
        )
        print(f"Retrying workflow {name}: {response}")

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Retries failed step function workflows.")
    parser.add_argument("--region", required=True, help="AWS region")
    parser.add_argument("--service", required=True, help="AWS service")
