Here's a simple example of a toast notification using React Context:

1. First, create a `ToastContext` file:

```javascript
import React, { createContext, useReducer } from 'react';

const initialState = {
  toast: null,
};

const toastReducer = (state, action) => {
  switch (action.type) {
    case 'SHOW_TOAST':
      return { ...state, toast: action.toast };
    case 'HIDE_TOAST':
      return { ...state, toast: null };
    default:
      return state;
  }
};

export const ToastContext = createContext(initialState);

export function ToastProvider({ children }) {
  const [state, dispatch] = useReducer(toastReducer, initialState);

  const showToast = (toast) => {
    dispatch({ type: 'SHOW_TOAST', toast });
  };

  const hideToast = () => {
    dispatch({ type: 'HIDE_TOAST' });
  };

  return (
    <ToastContext.Provider value={{ state, showToast, hideToast }}>
      {children}
    </ToastContext.Provider>
  );
}
```

2. Next, create a `Toast` component:

```javascript
import React from 'react';
import { useContext } from 'react';

function Toast() {
  const { state } = useContext(ToastContext);

  if (!state.toast) {
    return null;
  }

  return (
    <div className="toast">
      {state.toast.message}
      <button onClick={() => state.hideToast()}>Close</button>
    </div>
  );
}

export default Toast;
```

