Here's a Python function that meets your requirements:

```python
import re

def num_to_words(num, lang='en'):
    if lang not in ['en', 'fr', 'es', 'de']:
        raise ValueError('Invalid language')

    def digit_to_word(digit):
        if digit == 1:
            return 'one'
        elif digit == 2:
            return 'two'
        elif digit == 3:
            return 'three'
        elif digit == 4:
            return 'four'
        elif digit == 5:
            return 'five'
        elif digit == 6:
            return 'six'
        elif digit == 7:
            return 'seven'
        elif digit == 8:
            return 'eight'
        elif digit == 9:
            return 'nine'
        else:
            return 'ten'

    def thousands_to_words(num):
        words = []
        while num > 0:
            hundreds = num // 100
            tens = (num % 100) // 10
            ones = num % 10
            words.append(digit_to_word(hundreds))
            words.append('hundred')
            if tens != 0:
                words.append(digit_to_word(tens))
                words.append('and')
            words.append(digit_to_word(ones))
            num -= hundreds * 100 + tens * 10 + ones
        return ' '.join(reversed(words))

    if num < 0:
        return f'minus {thousands_to_words(-num)}'
    else:
        return thousands_to_words(num)

# Test cases
print(num_to_words(12345))  # Output: twelve thousand three hundred forty-five
print(num_to_words(-67890))  # Output: minus six hundred seventy-eight thousand nine hundred
print(num_to_words(123.456))  # Output: one hundred twenty-three point four five six
